<?php
/**
 * Portable wp-config sample for the Mööblipoisid site.
 *
 * - Under DDEV, the environment-specific public/wp-config.php is generated by
 *   `ddev start` and loads public/wp-config-ddev.php (also generated, gitignored).
 * - With the plain docker-compose.yml fallback, the wordpress image creates a
 *   wp-config.php from the WORDPRESS_DB_* environment variables (host `db`).
 * - On production (zone.ee), copy this file to wp-config.php and fill in the
 *   hosting MySQL credentials, unique salts, and the site URL.
 *
 * @package WordPress
 */

// DDEV settings (database + WP_HOME) win when running inside a DDEV web container.
if ( getenv( 'IS_DDEV_PROJECT' ) === 'true' && is_readable( __DIR__ . '/wp-config-ddev.php' ) ) {
	require_once __DIR__ . '/wp-config-ddev.php';
}

// Fallback database credentials: match docker-compose.yml (service `db`).
defined( 'DB_NAME' ) || define( 'DB_NAME', 'wordpress' );
defined( 'DB_USER' ) || define( 'DB_USER', 'wordpress' );
defined( 'DB_PASSWORD' ) || define( 'DB_PASSWORD', 'wordpress' );
defined( 'DB_HOST' ) || define( 'DB_HOST', 'db' );
defined( 'DB_CHARSET' ) || define( 'DB_CHARSET', 'utf8mb4' );
defined( 'DB_COLLATE' ) || define( 'DB_COLLATE', '' );

/**
 * Authentication unique keys and salts.
 * Generate a fresh set on production: https://api.wordpress.org/secret-key/1.1/salt/
 */
defined( 'AUTH_KEY' ) || define( 'AUTH_KEY', 'put your unique phrase here' );
defined( 'SECURE_AUTH_KEY' ) || define( 'SECURE_AUTH_KEY', 'put your unique phrase here' );
defined( 'LOGGED_IN_KEY' ) || define( 'LOGGED_IN_KEY', 'put your unique phrase here' );
defined( 'NONCE_KEY' ) || define( 'NONCE_KEY', 'put your unique phrase here' );
defined( 'AUTH_SALT' ) || define( 'AUTH_SALT', 'put your unique phrase here' );
defined( 'SECURE_AUTH_SALT' ) || define( 'SECURE_AUTH_SALT', 'put your unique phrase here' );
defined( 'LOGGED_IN_SALT' ) || define( 'LOGGED_IN_SALT', 'put your unique phrase here' );
defined( 'NONCE_SALT' ) || define( 'NONCE_SALT', 'put your unique phrase here' );

/**
 * WordPress database table prefix.
 */
$table_prefix = 'wp_';

// Site URL: define explicitly on production, e.g. https://mooblipoisid.ee
// defined( 'WP_HOME' );
// defined( 'WP_SITEURL' );

/** Enable dev logging locally if needed. */
// define( 'WP_DEBUG', true );
// define( 'WP_DEBUG_LOG', true );
// define( 'WP_DEBUG_DISPLAY', false );

/** Absolute path to the WordPress directory. */
if ( ! defined( 'ABSPATH' ) ) {
	define( 'ABSPATH', __DIR__ . '/' );
}

/** Sets up WordPress vars and included files. */
require_once ABSPATH . 'wp-settings.php';
